export const GAOPAI_WS_URL = 'ws://127.0.0.1:12345'

function escapeHtml(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

export function getGaopaiEnv(ws) {
  return {
    pageUrl: window.location.href,
    protocol: window.location.protocol,
    isHttps: window.location.protocol === 'https:',
    wsUrl: GAOPAI_WS_URL,
    wsReadyState: ws ? ws.readyState : null,
  }
}

export function logGaopai(step, msg, extra) {
  const time = new Date().toLocaleTimeString()
  const line = `[高拍仪排查] ${time} ${step} ${msg}`
  if (extra !== undefined) {
    console.log(line, extra)
  } else {
    console.log(line)
  }
}

export function notifyGaopaiFail(vm, step, reason, tips, ws) {
  const env = getGaopaiEnv(ws)
  logGaopai(step, reason, env)
  console.error('[高拍仪排查] 失败详情', { step, reason, tips, env })

  const httpsTip = env.isHttps
    ? '当前页面是 HTTPS，浏览器可能拦截了 ws:// 明文连接。请把 F12 控制台里 WebSocket 报错一并截图。'
    : ''
  const shortMsg = `${step}：${reason}`

  vm.$notify({
    title: '高拍仪排查失败',
    message: shortMsg,
    offset: 0,
    duration: 0,
    type: 'error',
  })

  const html = [
    `<div style="text-align:left;line-height:1.7;word-break:break-all;">`,
    `<p><b>失败步骤：</b>${escapeHtml(step)}</p>`,
    `<p><b>原因：</b>${escapeHtml(reason)}</p>`,
    `<p><b>页面地址：</b>${escapeHtml(env.pageUrl)}</p>`,
    `<p><b>页面协议：</b>${escapeHtml(env.protocol)}</p>`,
    `<p><b>连接地址：</b>${escapeHtml(env.wsUrl)}</p>`,
    httpsTip ? `<p style="color:#c00;"><b>注意：</b>${escapeHtml(httpsTip)}</p>` : '',
    tips ? `<p><b>建议：</b>${escapeHtml(tips)}</p>` : '',
    `<p style="color:#666;">详细日志在浏览器 F12 → Console，搜索「高拍仪排查」</p>`,
    `</div>`,
  ].join('')

  if (typeof vm.$alert === 'function') {
    return vm.$alert(html, '高拍仪排查失败', {
      type: 'error',
      dangerouslyUseHTMLString: true,
      confirmButtonText: '知道了',
    }).catch(() => {})
  }
  return Promise.resolve()
}
"}]

